"""Whole-file lessons on variable records and wildcard matching."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='가변 길이 레코드 · 파싱 · 문자열 알고리즘',
                     sections=sections, questions=questions))


add('include/linux/ihex.h', '바이너리 IHEX 전체: 레코드 순회와 펌웨어 수명',
    '텍스트 Intel HEX를 커널에서 직접 해석하는 대신 주소와 데이터 길이를 가진 바이너리 레코드를 사용합니다.',
    'packed 헤더 뒤에 가변 길이 데이터를 두고 다음 레코드는 4바이트 경계로 이동합니다. 펌웨어 요청과 형식 검증을 묶고 실패하면 참조를 해제합니다.',
    '형식 검증의 의도와 실제 산술 경계를 구분합니다. 이 고정 버전에는 짧은 파일 크기와 16비트 길이 합산을 별도 거부하는 코드가 없습니다.',
    [('전체 파일 구조', 'SPDX, 바이너리 표현의 목적 설명, include guard, types/firmware/device 헤더 뒤에 packed 구조체와 inline 함수 다섯 개가 있습니다. 크기 계산, 무조건 다음 레코드, 종료 확인을 포함한 다음 레코드, 검증, 요청 및 검증의 순서입니다.'),
     ('자료구조와 엔디언', 'ihex_binrec은 __be32 addr, __be16 len, uint8_t data[]를 가집니다. packed이므로 고정 헤더는 6바이트이고 데이터는 그 뒤부터 시작합니다. flexible array는 sizeof에 데이터 공간을 포함하지 않습니다. len은 be16_to_cpu로 변환하며 addr도 사용할 때 바이트 순서를 고려해야 합니다. 주석은 원래 텍스트 형식보다 큰 레코드를 지원하기 위해 길이를 16비트로 확장했다고 설명합니다.'),
     ('크기와 정렬 예제', 'ihex_binrec_size는 데이터 길이에 sizeof(*p)를 더하지만 반환 타입은 uint16_t입니다. 정상 길이 3이면 9를 반환하고 __ihex_next_binrec은 ALIGN(9,4)=12바이트 이동합니다. 레코드 구조체가 packed라는 사실과 레코드 시작을 4바이트 단위로 배치하는 정책은 서로 다릅니다. void 포인터에 바이트 수를 더하는 표현은 커널이 사용하는 GNU C 확장입니다.'),
     ('길이 합산의 좁아짐', '16비트 len의 최대값은 65535인데 헤더 6을 더한 반환형도 16비트입니다. len65530이면 65536이 uint16_t에서 0으로 줄어들고 다음 위치 증가도 0입니다. 따라서 큰 레코드를 무조건 안전하게 순회한다고 주장할 수 없습니다. 이 경계는 실제 선언과 산술에서 도출되며 수업에서 무한 순회가 가능한 입력을 실행하는 것은 필요하지 않습니다.'),
     ('종료 표식', 'ihex_next_binrec은 먼저 다음 레코드로 이동한 뒤 그 레코드의 len이 0이면 NULL을 반환합니다. 현재 레코드가 0인지 먼저 검사하는 함수가 아닙니다. 경계 길이 인자가 없으므로 유효한 형식과 접근 가능한 다음 헤더를 전제로 합니다.'),
     ('검증 루프가 실제로 검사하는 것', 'ihex_validate_fw는 마지막 6바이트 위치를 end로 잡고 rec<=end 동안 순회합니다. rec==end이고 len0일 때만 성공합니다. 중간의 len0은 즉시 성공이나 즉시 오류가 아니라 다음 정렬 위치로 계속 이동합니다. 레코드 주소의 장치별 타당성이나 데이터 checksum은 검사하지 않습니다.'),
     ('검증의 산술 전제', 'fw->size에서 헤더 크기를 빼기 전에 size>=6을 검사하지 않습니다. 매우 짧은 입력의 뺄셈과 포인터 계산을 안전하다고 볼 수 없습니다. 앞서 본 크기 반환의 wrap도 별도로 검사하지 않아 순회가 진행하지 않을 수 있습니다. 함수 이름과 주석의 검증 의도가 모든 악성 입력에 대한 방어 증거는 아닙니다.'),
     ('요청과 실패 정리', 'request_ihex_firmware는 request_firmware 실패를 그대로 반환합니다. 성공하면 지역 lfw를 검증하고 실패 시 dev_err로 이름을 기록한 뒤 release_firmware를 호출합니다. 검증 성공일 때만 *fw에 lfw를 대입합니다. 성공 후 펌웨어 해제 책임은 호출자에게 넘어가며 실패 시 외부 출력 포인터를 먼저 덮어쓰지 않습니다.'),
     ('CS 연결', '외부 바이트 순서, flexible array, packed 레이아웃, 정렬 올림, 정수 폭, 반복문의 진행 조건, 소유권 이전과 실패 원자성을 연결합니다. 원본의 한계까지 설명하는 학습 자료이며 커널 구현을 수정한 것으로 간주하지 않습니다.')],
    [('데이터 길이가 3인 레코드의 다음 시작까지 거리는?', '12바이트다', '3바이트다', '고정 헤더 6에 데이터 3을 더하면 9입니다. 다음 시작은 4바이트 정렬이므로 12만큼 이동합니다.'),
     ('len65530에서 크기 helper의 uint16_t 결과는?', '0이 된다', '65536을 그대로 반환한다', '65530+6=65536은 16비트 unsigned 반환형에 담을 수 없어 0으로 줄어듭니다. 다음 위치가 진행하지 않을 수 있습니다.'),
     ('검증 도중 중간 len0을 만나면 바로 성공하는가?', '아니다. 마지막 헤더 위치와 일치해야 성공한다', '그렇다. 위치는 검사하지 않는다', '성공 조건은 rec==end와 len0을 동시에 요구합니다. 중간 0 길이는 그 조건을 충족하지 못합니다.'),
     ('펌웨어 요청 성공 후 검증이 실패하면?', '지역 펌웨어 참조를 해제하고 오류를 반환한다', '출력 포인터에 먼저 넣고 호출자에게 정리를 맡긴다', '실패 분기에 release_firmware(lfw)가 있고 *fw 대입은 성공 경로 끝에만 있습니다.')])

add('lib/glob.c', 'Glob 전체 알고리즘: 최근 별표로 돌아가는 비재귀 매칭',
    '장치 패턴 목록 등에 쓰는 작은 셸 스타일 문자열 매칭 구현입니다.',
    '패턴과 문자열을 함께 이동하며 가장 최근 *의 위치를 저장합니다. 불일치하면 그 별표가 소비하는 문자열을 한 글자 늘리고 재시도합니다.',
    '문자열 전체를 매칭하며 경로 전용 규칙이나 정규표현식을 기대하면 안 됩니다. 입력은 읽을 수 있는 NUL 종료 문자열이어야 합니다.',
    [('파일 전체와 모듈 정보', 'module/glob 헤더, 모듈 설명과 Dual MIT/GPL 라이선스, glob_match 함수, EXPORT_SYMBOL로 구성됩니다. 주석은 의존하는 ATA 코드가 모듈일 수 있어 이 코드도 모듈로 만들 수 있음을 설명합니다. 패턴 사전 처리나 별도 힙 할당은 없습니다.'),
     ('기본 순회와 전체 일치', '매 반복에서 문자열 문자 c와 패턴 문자 d를 unsigned char로 읽고 각 포인터를 증가시킵니다. 리터럴 문자가 같으면 계속하고 두 문자가 모두 NUL이면 성공합니다. 패턴의 일부가 맞았다는 이유만으로 성공하지 않습니다. 단, 패턴 끝의 *는 남은 모든 문자열을 소비할 수 있어 바로 성공합니다.'),
     ('물음표와 별표', '?는 NUL을 제외한 문자 하나를 소비합니다. *는 back_pat에 그 뒤의 패턴 위치를, back_str에 현재 문자열 위치를 저장합니다. 이미 증가한 str을 한 칸 되돌려 처음에는 길이 0 매치를 시도합니다. 불일치 시 pat을 back_pat로 돌리고 str을 ++back_str로 정해 별표의 소비량을 늘립니다.'),
     ('되돌아갈 지점 하나로 충분한 이유', '*가 /를 포함한 모든 문자를 허용하므로 이전 별표까지 여러 단계로 되돌아갈 필요 없이 최근 별표 이후의 정렬을 조정할 수 있습니다. 재귀 호출이나 스택을 쓰지 않고 두 위치만 보관합니다. 문자열 끝에서 불일치하거나 저장된 별표가 없으면 실패합니다.'),
     ('문자 클래스', '[...] 안에서는 단일 문자와 a-b 범위를 순회하며 해당 여부를 OR합니다. 첫 !는 결과를 반전합니다. 첫 범위의 시작 문자가 ]일 수 있어 []a]는 ]와 a를 포함합니다. - 바로 뒤가 ]이면 범위로 처리하지 않습니다. 역방향 z-a는 a<=c<=b를 만족하지 않아 그 범위로는 일치하지 않습니다.'),
     ('닫히지 않은 클래스와 이스케이프', '클래스 해석 도중 NUL을 만나면 literal로 가서 원래 [를 문자로 비교합니다. 따라서 닫는 ]가 없는 [abc는 같은 리터럴 문자열과 매칭할 수 있습니다. 역슬래시는 다음 패턴 문자를 d로 읽어 리터럴 경로로 보냅니다. 정상 예로 역슬래시 뒤 *는 별표 문자 자체를 뜻합니다. 이 구현은 클래스 안의 백슬래시에 별도의 이스케이프 분기를 제공하지 않습니다.'),
     ('셸 및 정규표현식과 차이', '/와 선행 .를 특별 취급하지 않으므로 *는 .hidden이나 a/b에도 매칭합니다. 클래스 부정은 !이며 ^는 정규표현식처럼 부정 연산자가 아닙니다. [^a]는 ^ 또는 a를 허용하는 클래스입니다. 바이트 기반 비교이므로 UTF-8의 여러 바이트 문자를 ? 하나로 처리하는 유니코드 매처가 아닙니다.'),
     ('시간과 공간 복잡도', '패턴 전처리가 없고 최근 별표 다음 패턴을 여러 시작점에서 다시 검사할 수 있습니다. 주석의 *aaaaa와 aaaaaaaaaa 예는 성공까지 패턴을 여섯 번 통과합니다. 최악 시간은 문자열 길이와 패턴 길이의 곱에 비례하고 보조 공간은 상수입니다. 모든 와일드카드 매칭이 선형 시간이라고 일반화하지 않습니다.'),
     ('CS 연결', '유한 상태와 포인터, 제한된 backtracking, 전체 일치와 부분 일치, 토큰 해석, 바이트 문자 집합을 학습합니다. __pure는 입력이 같아도 다른 곳에서 입력 메모리를 바꾸면 결과가 달라질 수 없는 절대 상수 함수라는 뜻이 아닙니다. 함수는 전달된 문자열 메모리를 읽습니다.')],
    [('패턴 *는 a/b와 .hidden에 매칭하는가?', '둘 다 매칭한다', '슬래시와 선행 점 때문에 둘 다 실패한다', '이 구현은 경로 구분자나 선행 점을 특별 취급하지 않습니다. 별표는 남은 모든 문자를 허용합니다.'),
     ('[^a]는 a를 제외한 모든 문자를 뜻하는가?', '아니다. ^와 a를 포함하는 클래스다', '그렇다. 정규표현식의 부정 클래스와 같다', '반전 여부는 첫 문자가 !인지로만 정합니다. ^는 일반 문자로 처리됩니다.'),
     ('별표 이후 불일치가 발생하면 무엇을 바꾸는가?', '최근 별표의 문자열 소비량을 한 글자 늘린다', '항상 재귀로 모든 과거 별표를 탐색한다', 'pat=back_pat, str=++back_str로 재시도합니다. 별도 재귀나 여러 단계의 저장 스택은 없습니다.'),
     ('최악 시간 복잡도는?', '문자열 길이와 패턴 길이의 곱에 비례한다', '입력과 무관하게 상수 시간이다', '별표 다음 패턴을 여러 문자열 시작점에서 다시 검사할 수 있습니다. 보조 공간이 상수라고 시간도 상수인 것은 아닙니다.')])

add('include/linux/glob.h', 'Glob 공개 헤더 전체: bool 결과와 pure 계약',
    'glob_match 하나를 다른 커널 코드에 노출하는 작은 인터페이스입니다.',
    '패턴과 문자열 두 개를 const char 포인터로 받고 bool 일치 여부를 반환합니다.',
    '이 선언은 버퍼 길이 검사를 추가하지 않습니다. 호출자는 NUL 종료와 유효한 수명을 보장해야 합니다.',
    [('전체 내용', 'GPL SPDX, _LINUX_GLOB_H guard, bool용 linux/types.h와 __pure용 linux/compiler.h 포함, 함수 선언 하나, endif로 끝납니다. 문자 클래스나 별표의 세부 문법은 lib/glob.c에 있습니다.'),
     ('const와 반환값', 'char const *는 함수가 해당 포인터를 통해 문자를 변경하지 않는 계약입니다. 호출 중 다른 주체가 메모리를 변경해도 안전하다는 보장은 아닙니다. bool은 일치/불일치만 나타내며 오류 코드나 매칭된 구간을 반환하지 않습니다.'),
     ('__pure의 의미', '컴파일러가 함수의 관찰 가능한 부작용과 메모리 읽기 관계를 고려해 호출을 최적화하도록 돕는 속성입니다. 문자열 내용을 읽을 수 있으며, 포인터 주소가 같다는 것만으로 메모리가 변경된 뒤에도 결과가 같다고 가정할 수는 없습니다.'),
     ('CS 연결', '선언과 구현의 분리, 읽기 전용 포인터, 입력 수명, 불리언 API와 오류 채널의 차이, 컴파일러 속성을 학습합니다.')],
    [('glob_match가 매칭된 부분 문자열 주소를 반환하는가?', '아니다. bool로 일치 여부만 반환한다', '그렇다. 첫 매칭 위치를 반환한다', '선언의 반환형은 bool입니다. 부분 위치나 오류 번호를 전달하는 별도 출력 인자가 없습니다.'),
     ('const char *이면 NUL 종료도 자동 보장되는가?', '아니다. 호출자가 입력 형식을 보장해야 한다', '그렇다. const가 길이와 종료를 검증한다', 'const는 그 포인터를 통한 수정 제한입니다. 길이 검사나 종료 문자를 자동으로 추가하지 않습니다.')])
